#!/usr/bin/env bash
# Writes the root Package.swift that exposes the released XCFrameworks to Swift
# Package Manager as remote binary targets:
#   - PeeknikoKit:     the real inspector with SQLDelight storage (PeeknikoCore.xcframework),
#                      wrapped in library-ios/swift so SQLite is linked automatically
#   - PeeknikoKitNoop: the no-op stand-in for production builds (PeeknikoCoreNoop.xcframework)
# Both frameworks have the Swift module name PeeknikoCore, so app code always uses
# `import PeeknikoCore`. Link only one of the two products into a given app target.
#
# Usage: generate-package-swift.sh <version> <core-url> <core-checksum> <noop-url> <noop-checksum> [output]
set -euo pipefail

if [[ $# -lt 5 || $# -gt 6 ]]; then
  echo "Usage: $0 <version> <core-url> <core-checksum> <noop-url> <noop-checksum> [output]" >&2
  exit 1
fi

version="$1"
core_url="$2"
core_checksum="$3"
noop_url="$4"
noop_checksum="$5"
output="${6:-Package.swift}"

for checksum in "$core_checksum" "$noop_checksum"; do
  if [[ ! "$checksum" =~ ^[0-9a-f]{64}$ ]]; then
    echo "Invalid checksum '$checksum': expected 64 lowercase hex characters" >&2
    exit 1
  fi
done

cat > "$output" <<EOF
// swift-tools-version: 5.9
// Generated by .github/scripts/generate-package-swift.sh for Peekniko ${version}. Do not edit.
import PackageDescription

let package = Package(
    name: "PeeknikoKit",
    platforms: [.iOS(.v17)],
    products: [
        // The inspector. Link it into debug/internal app targets.
        .library(name: "PeeknikoKit", targets: ["PeeknikoKit"]),
        // Same API that does nothing. Link it into production app targets instead.
        .library(name: "PeeknikoKitNoop", targets: ["PeeknikoCoreNoop"]),
    ],
    targets: [
        // Binary targets can't declare linker settings, so this wrapper links SQLite
        // for the SQLDelight storage bundled in PeeknikoCore.
        .target(
            name: "PeeknikoKit",
            dependencies: ["PeeknikoCore"],
            path: "library-ios/swift",
            linkerSettings: [.linkedLibrary("sqlite3")]
        ),
        .binaryTarget(
            name: "PeeknikoCore",
            url: "${core_url}",
            checksum: "${core_checksum}"
        ),
        .binaryTarget(
            name: "PeeknikoCoreNoop",
            url: "${noop_url}",
            checksum: "${noop_checksum}"
        ),
    ]
)
EOF

echo "Wrote $output for ${version}"
